import{z as s,x as n,o as A,c as d,q as t,j as i,D as e,d as l,s as r,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"衍生与合并的许可","description":"","frontmatter":{"title":"衍生与合并的许可","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/eco-derivative-merge-license.md","filePath":"llm/eco-derivative-merge-license.md","lastUpdated":1791413859000}'),p={name:"llm/eco-derivative-merge-license.md"};function m(h,E,D,c,C,F){const B=n("Mermaid");return A(),d("div",null,[E[2]||(E[2]=t('<h1 id="衍生与合并的许可" tabindex="-1">衍生与合并的许可 <a class="header-anchor" href="#衍生与合并的许可" aria-label="Permalink to &quot;衍生与合并的许可&quot;">​</a></h1><div class="epigraph"><p>参数空间的距离量不出法律距离：两个权重文件插值一次，同时带着两份许可的出处走进下游。</p><footer>—— 据 MergeKit 类合并工具与 Llama 社区许可、Apache 2.0 对衍生作品条款的对照整理</footer></div><p><a href="/llm/eco-weight-license-terms">上一课</a>给了五段读法，让你能拆开一份许可。权重一旦被公开，下游立刻会做的事是改它：LoRA 适配器、全参微调、多模型合并、量化再发布、蒸馏小模型。每条产线的输出该挂什么许可，谁背什么义务，本课记账。后课的模型卡要把这笔账写进发布物，所以先在这里把规则立起来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合并两条权重的产物挂什么许可，是社区里最常见也最容易被含糊带过的问题。一个 Llama 系底座加一个 Apache 2.0 底座线性插值，模型卡上随手写 Apache 2.0 的例子并不少见。类似的问题沿产线分布：在 Llama 底座上训练的 LoRA 适配器能不能单独按宽松许可发布？把某个开源权重蒸馏进自己从零训练的小模型，算不算衍生？把权重量化成 GGUF 再分发，义务跟着变不变？这些问题没有一个统一的「社区惯例」答案，缺口是一套保守、可执行的记账规则。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规则只有一条骨架：<strong>输出继承输入中最严格的那份许可</strong>。两份权重合并，输出同时携带两边的出处，合规口径按更严格的那份走——一边是 Llama 社区许可，输出就按它的命名、规模与政策义务处理；两边都是 Apache 2.0，输出仍需保留 NOTICE 与修改声明。配套动作是<strong>血缘台账</strong>：记录底座模型与其 revision、适配器与其训练底座、合并配方与权重比、量化的源文件。发布时把血缘写进模型卡的 <code>base_model</code> 链，让下游自己也能算一遍。<span class="marginnote">为什么台账要细到 revision？同一个模型名的不同版本可能挂不同许可——某底座 v1 是宽松条款、v2 换成更严的社区许可是真实发生过的事。半年后法务或平台方来问「你这版产品用的到底是哪个底座」，台账能让你一天内答出来；没有台账，就只能面对一堆权重文件从头逆向，而那时答案可能已经改不动产线了。</span>选型的前瞻规则放在台账之前：要出商业产品，就从宽松许可的底座出发，不要把改不动的依赖引进产线。</p>',7)),(A(),i(o,null,{default:e(()=>[r(B,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%BE%93%E5%85%A5%20A%EF%BC%9A%E8%AE%B8%E5%8F%AF%E4%B8%8E%20revision%22%5D%20--%3E%20M%5B%22%E5%90%88%E5%B9%B6%20%2F%20%E9%80%82%E9%85%8D%20%2F%20%E9%87%8F%E5%8C%96%22%5D%0A%20%20B%5B%22%E8%BE%93%E5%85%A5%20B%EF%BC%9A%E8%AE%B8%E5%8F%AF%E4%B8%8E%20revision%22%5D%20--%3E%20M%0A%20%20M%20--%3E%20LED%5B%22%E8%A1%80%E7%BC%98%E5%8F%B0%E8%B4%A6%EF%BC%9A%E5%BA%95%E5%BA%A7%E3%80%81%E9%85%8D%E6%96%B9%E3%80%81%E6%AF%94%E4%BE%8B%22%5D%0A%20%20LED%20--%3E%20S%5B%22%E6%8C%89%E6%9C%80%E4%B8%A5%E6%A0%BC%E8%AE%B8%E5%8F%AF%E5%AE%9A%E8%BE%93%E5%87%BA%E5%8F%A3%E5%BE%84%22%5D%0A%20%20S%20--%3E%20CARD%5B%22%E5%86%99%E8%BF%9B%E6%A8%A1%E5%9E%8B%E5%8D%A1%20base_model%20%E9%93%BE%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"这条骨架的版权学基础是「衍生作品」概念，但它的边界在权重上恰好是模糊的：线性插值 \\(\\theta=\\alpha\\theta_A+(1-\\alpha)\\theta_B\\) 是复制、改编还是新型使用，多数司法辖区没有成熟判例，本课不假装有定论。保守策略的理由正是模糊本身：定性未定时，按最严口径记账的成本是「多写几行声明」，按最宽口径记账的风险是整条产线的合规地基。蒸馏是另一条线：用输出训练新权重通常更接近「学习」而非「拷贝」，一般不产生衍生权重，但个别条款对输出的使用另有要求，仍要回到上一课的第四段逐条读。量化再分发是复制加格式转换，授予范围内的再分发义务原样继承——变化的是打包格式，不是义务。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"在 Llama 底座上训练的 LoRA 适配器，单独发布时按社区口径通常随底座许可走；把它挂在 Apache 2.0 模型下「借壳」洗成宽松许可，是血缘台账要拦住的典型操作。")],-1)),E[6]||(E[6]=a("p",null,"落到具体产线，可以用一个问题把判断收拢：输出里有没有原权重的拷贝或修改。",-1)),(A(),i(o,null,{default:e(()=>[r(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BF%99%E6%9D%A1%E4%BA%A7%E7%BA%BF%E7%9A%84%E8%BE%93%E5%87%BA%E7%AE%97%E4%B8%8D%E7%AE%97%E8%A1%8D%E7%94%9F%22%5D%20--%3E%7C%E5%90%88%E5%B9%B6%20%2F%20LoRA%20%2F%20%E9%87%8F%E5%8C%96%7C%20YES%5B%22%E7%AE%97%EF%BC%9A%E6%9D%83%E9%87%8D%E8%A2%AB%E6%8B%B7%E8%B4%9D%E6%88%96%E4%BF%AE%E6%94%B9%22%5D%0A%20%20Q%20--%3E%7C%E8%92%B8%E9%A6%8F%EF%BC%9A%E4%BB%85%E7%94%A8%E8%BE%93%E5%87%BA%E8%AE%AD%E7%BB%83%7C%20NO%5B%22%E9%80%9A%E5%B8%B8%E4%B8%8D%E7%AE%97%EF%BC%9A%E6%96%B0%E6%9D%83%E9%87%8D%E4%BB%8E%E6%95%B0%E6%8D%AE%E5%AD%A6%E5%87%BA%22%5D%0A%20%20YES%20--%3E%20STRICT%5B%22%E6%8C%82%E8%BE%93%E5%85%A5%E4%B8%AD%E6%9C%80%E4%B8%A5%E6%A0%BC%E7%9A%84%E8%AE%B8%E5%8F%AF%22%5D%0A%20%20NO%20--%3E%20READ%5B%22%E4%BB%8D%E9%80%90%E6%9D%A1%E8%AF%BB%E7%AC%AC%E5%9B%9B%E6%AE%B5%EF%BC%9A%E8%BE%93%E5%87%BA%E7%94%A8%E9%80%94%E9%99%90%E5%88%B6%22%5D%0A%20%20STRICT%20--%3E%20CARD%5B%22%E8%A1%80%E7%BC%98%E5%86%99%E8%BF%9B%20base_model%20%E9%93%BE%22%5D%0A%20%20READ%20--%3E%20CARD%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=t('<p><span class="marginnote">插值公式 \\(\\theta=\\alpha\\theta_A+(1-\\alpha)\\theta_B\\) 可以读作「按比例掺两份权重」：\\(\\alpha=0.7\\) 就是每个参数位置取七成 A 加三成 B。掺完的每一个数里都同时带着 A 和 B 的血统，物理上分不开——这正是「输出继承最严格许可」的直观原因：你交出去的东西没法只认一方出处。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的每一条都是工程策略，不是法律结论：合并的定性、蒸馏的定性、适配器独立作品的资格，都随法辖区与具体条款浮动。台账的价值在于无论结论怎么变，你能在一天内重算一遍口径，而不是面对「当时谁也说不清底座是哪个」的废墟。宽松许可之间的合并不等于零义务，NOTICE 与修改声明照样跟着走，这与<a href="/llm/code-license-gate">代码许可门</a>里对依赖的处理同构。<span class="marginnote">初学者容易把「宽松许可」理解成「随便用、什么都不用管」。实际上 Apache 2.0 这类宽松许可的「宽松」指的是能商用、能闭源衍生，义务只是轻——保留原始 NOTICE、标注你改过哪些文件，这些一样不能省。两家宽松许可的权重合并，产物要同时带两份声明，漏了就是违约，跟许可严不严没有关系。</span>最后，最严口径解决的是「输出挂什么」，不解决「输入当年拿得干不干净」：底座本身的许可有瑕疵，台账只能暴露问题，不能治愈问题。下一课把这笔账连同数据卡一起写进发布物。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>记账骨架一条：输出继承输入中最严格的许可；配套血缘台账，发布时写进 <code>base_model</code> 链。</li><li>合并的版权定性在多数辖区无定论，保守口径的理由是模糊本身。</li><li>蒸馏通常不产生衍生权重，但个别条款对输出另有要求，逐条读第四段。</li><li>量化再分发继承原许可义务，格式转换不改变合规账。</li><li>商业产品从宽松底座出发，别引进改不动的依赖；代码侧同构规则见代码许可门。</li><li>出处：Llama 社区许可与 Apache 2.0 衍生条款对照；MergeKit 类工具社区口径，按本课程整理。</li></ul>',5))])}const f=s(p,[["render",m]]);export{u as __pageData,f as default};
